   player.loungePose?.(lastClock,active.kind,progress,{seatHeight:seat.seatHeight??seat.position?.[1]??0,blend,pageTurn:lastClock<pageTurnUntil?Math.max(0,1-(pageTurnUntil-lastClock)/.8):0});
   syncCup(blend);
